/**
 * Generates supabase/seed.sql from the demo catalogue in src/lib/catalogue.
 * Run:  npm run db:seed:generate
 */
import { writeFileSync } from "node:fs";
import { CATEGORIES } from "../src/lib/catalogue/categories";
import { SEED_SERVICES } from "../src/lib/catalogue/services";

const q = (v: string | null | undefined) => (v == null ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const arr = (a: string[]) => `array[${a.map(q).join(",")}]::text[]`;
const json = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const out: string[] = [
  "-- AUTO-GENERATED by scripts/generate-seed.ts — do not edit by hand.",
  "-- All services are DEMO records (verification_status = 'demo') until verified by an editor.",
  "begin;",
  "",
];

for (const c of CATEGORIES) {
  out.push(
    `insert into public.categories (slug, name, name_hi, description, description_hi, icon, keywords, sort_order) values (${q(c.slug)}, ${q(c.name)}, ${q(c.nameHi)}, ${q(c.description)}, ${q(c.descriptionHi)}, ${q(c.icon)}, ${arr(c.keywords)}, ${c.sortOrder}) on conflict (slug) do nothing;`,
  );
}
out.push("");

SEED_SERVICES.forEach((s, i) => {
  out.push(
    `insert into public.services (slug, category_id, kind, title, title_hi, summary, summary_hi, overview, benefits, eligibility, documents, process, important_dates, faqs, official_source_name, official_url, fee_paise, assistance_scope, verification_status, is_popular, is_trending, is_published, sort_order)
select ${q(s.slug)}, c.id, ${q(s.kind)}, ${q(s.title)}, ${q(s.titleHi)}, ${q(s.summary)}, ${q(s.summaryHi)}, ${q(s.overview)}, ${arr(s.benefits)}, ${arr(s.eligibility)}, ${arr(s.documents)}, ${arr(s.process)}, ${json(s.importantDates)}, ${json(s.faqs)}, ${q(s.officialSourceName)}, ${q(s.officialUrl)}, ${s.feePaise ?? "null"}, ${arr(s.assistanceScope)}, 'demo', ${!!s.isPopular}, ${!!s.isTrending}, true, ${i}
from public.categories c where c.slug = ${q(s.category)}
on conflict (slug) do nothing;`,
  );
  if (s.keywords.length) {
    out.push(
      `insert into public.service_keywords (service_id, keyword) select sv.id, k from public.services sv, unnest(${arr(s.keywords)}) as k where sv.slug = ${q(s.slug)} on conflict do nothing;`,
    );
  }
});

out.push("");
const faqs: [string, string, string, string][] = [
  ["Is Sabkaam a government website?", "No. Sabkaam is a private assistance platform and is not affiliated with any government department. We link to official portals for every service.", "क्या सबकाम सरकारी वेबसाइट है?", "नहीं। सबकाम एक निजी सहायता प्लेटफ़ॉर्म है और किसी सरकारी विभाग से संबद्ध नहीं है। हम हर सेवा के लिए आधिकारिक पोर्टल का लिंक देते हैं।"],
  ["Is browsing free?", "Yes. Searching and reading about any scheme or service is completely free. You only pay if you choose paid application assistance.", "क्या जानकारी देखना मुफ़्त है?", "हाँ। किसी भी योजना या सेवा को खोजना और पढ़ना पूरी तरह मुफ़्त है। आप केवल तभी भुगतान करते हैं जब आप सशुल्क सहायता चुनते हैं।"],
  ["Do you guarantee approval?", "No. Approval is always decided by the government department, bank or authority. We help you apply correctly and completely.", "क्या आप स्वीकृति की गारंटी देते हैं?", "नहीं। स्वीकृति हमेशा सरकारी विभाग, बैंक या संस्था तय करती है। हम सही और पूरा आवेदन करने में मदद करते हैं।"],
  ["Are government fees included in your fee?", "No. Our fee is only for our assistance. Any official fee is paid by you directly on the official portal.", "क्या सरकारी शुल्क आपके शुल्क में शामिल है?", "नहीं। हमारा शुल्क केवल हमारी सहायता के लिए है। कोई भी सरकारी शुल्क आप सीधे आधिकारिक पोर्टल पर देते हैं।"],
  ["How are my documents protected?", "Documents are stored in private, access-controlled storage and are only visible to you and the staff handling your request. We only ask for documents needed for your chosen service.", "मेरे दस्तावेज़ कैसे सुरक्षित हैं?", "दस्तावेज़ निजी, नियंत्रित स्टोरेज में रखे जाते हैं और केवल आपको और आपके अनुरोध पर काम करने वाले स्टाफ़ को दिखते हैं।"],
  ["Can I get a refund?", "Refunds follow our Refund Policy — for example, if we are unable to proceed with your request before work starts.", "क्या मुझे रिफंड मिल सकता है?", "रिफंड हमारी रिफंड नीति के अनुसार होते हैं — उदाहरण के लिए, यदि काम शुरू होने से पहले हम आपके अनुरोध पर आगे नहीं बढ़ पाते।"],
];
faqs.forEach(([qq, a, qh, ah], i) => {
  out.push(`insert into public.faqs (question, answer, question_hi, answer_hi, sort_order) select ${q(qq)}, ${q(a)}, ${q(qh)}, ${q(ah)}, ${i} where not exists (select 1 from public.faqs where question = ${q(qq)});`);
});

out.push("");
out.push(`insert into public.site_content (key, value_en, value_hi) values ('announcement', '', '') on conflict (key) do nothing;`);
out.push(`insert into public.site_content (key, value_en, value_hi) values ('hero_description', '', '') on conflict (key) do nothing;`);
out.push("", "commit;", "");

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), out.join("\n"));
console.log(`Wrote supabase/seed.sql — ${CATEGORIES.length} categories, ${SEED_SERVICES.length} services, ${faqs.length} FAQs`);
